def lamp_cmd(speed, door_open, night, fault):
    if fault:
        return "OFF"
    if night and speed > 0:
        return "LOW"
    if door_open:            # 고치기 전
        return "ROOM"
    return "OFF"

# 요구: 실내등은 정차 중에 문이 열렸을 때만 켠다
def test_day_drive():
    assert lamp_cmd(30, True, False, False) == "OFF"
